Stack<Integer> s = new Stack<Integer>();
s.push(6);
s.push(1);
s.push(9);
s.push(5);
System.out.println("סעיף א: " + maxStack(s));
System.out.println("סעיף ב: " + contains(s, 1) + " " + contains(s, 4));
System.out.println("המחסנית אחרי: " + s);
